-- 609: Original BrillaPrep Cambridge IGCSE Physics (0625) Motion, Forces and Energy practice questions (batch igcse-physics-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ material.
PRAGMA foreign_keys = ON;
CREATE TABLE _migration_609_expected (id TEXT PRIMARY KEY, topic_id TEXT, subject_id TEXT, exam_type_id TEXT, paper_type_id TEXT, past_paper_id TEXT, question_text TEXT, question_type TEXT, round_type TEXT, options TEXT, correct_answer TEXT, explanation TEXT, difficulty TEXT, points INTEGER, marks INTEGER, time_limit INTEGER, question_number INTEGER, section TEXT, is_compulsory INTEGER, image_url TEXT, syllabus_topic_id TEXT, command_word TEXT, assessment_objective TEXT, source_paper_code TEXT, source_question_number TEXT, exam_board_id TEXT);
INSERT INTO _migration_609_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igphy_mechanics_s3_001', 'topic_igcse_physics_mechanics', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A car travelling at 20 m/s brakes uniformly to rest in 5.0 s. What distance does the car travel while braking?', 'multiple_choice', NULL, '["A. 50 m","B. 100 m","C. 8 m","D. 4 m"]', 'A', 'The deceleration is a = Δv ÷ t = 20 ÷ 5.0 = 4.0 m/s². Because the deceleration is uniform, the average velocity while braking is (20 + 0) ÷ 2 = 10 m/s, so the distance is 10 × 5.0 = 50 m (equivalently s = ut + ½at² = 100 − 50 = 50 m). (100 m uses s = vt and ignores the deceleration entirely; 8 m confuses the distance with the quantity 2a.) Therefore the correct answer is A: 50 m.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_mechanics_s3_002', 'topic_igcse_physics_mechanics', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A ball is thrown vertically upwards with an initial velocity of 30 m/s. Taking the gravitational field strength as 10 N/kg and neglecting air resistance, what is the maximum height the ball reaches?', 'multiple_choice', NULL, '["A. 90 m","B. 45 m","C. 15 m","D. 3 m"]', 'B', 'At maximum height the velocity is zero. Using v² = u² + 2as with a = −g = −10 m/s²: 0 = 30² − 2 × 10 × h, so h = 900 ÷ 20 = 45 m. (90 m omits the factor of 2 in the term 2as; 15 m halves the initial speed instead of squaring it.) Therefore the correct answer is B: 45 m.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_mechanics_s3_003', 'topic_igcse_physics_mechanics', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A cyclist starts from rest and accelerates along a straight, level road.', 'structured', NULL, NULL, '(a) Acceleration is the rate of change of velocity — the change in velocity divided by the time taken — measured in metres per second squared (m/s²). (b) Acceleration a = (v − u) ÷ t = (12 − 0) ÷ 6.0 = 2.0 m/s². (c) Resultant force F = ma = 80 × 2.0 = 160 N.', '(a) Acceleration is the rate of change of velocity — the change in velocity divided by the time taken — measured in metres per second squared (m/s²). (b) Acceleration a = (v − u) ÷ t = (12 − 0) ÷ 6.0 = 2.0 m/s². (c) Resultant force F = ma = 80 × 2.0 = 160 N.', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
CREATE TABLE _migration_609_expected_parts (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, part_label TEXT NOT NULL, part_text TEXT NOT NULL, marks INTEGER NOT NULL, correct_answer TEXT NOT NULL, display_order INTEGER NOT NULL);
INSERT INTO _migration_609_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_igphy_mechanics_s3_003_a', 'q_igphy_mechanics_s3_003', 'a', 'Define acceleration.', '1', 'Acceleration is the rate of change of velocity — the change in velocity divided by the time taken — measured in metres per second squared (m/s²).', '1'),
('sqp_q_igphy_mechanics_s3_003_b', 'q_igphy_mechanics_s3_003', 'b', 'The cyclist reaches a velocity of 12 m/s in 6.0 s. Calculate the acceleration of the cyclist.', '2', 'Acceleration a = (v − u) ÷ t = (12 − 0) ÷ 6.0 = 2.0 m/s².', '2'),
('sqp_q_igphy_mechanics_s3_003_c', 'q_igphy_mechanics_s3_003', 'c', 'The total mass of the cyclist and bicycle is 80 kg. Calculate the resultant force producing this acceleration.', '2', 'Resultant force F = ma = 80 × 2.0 = 160 N.', '3');
CREATE TABLE IF NOT EXISTS _migration_609_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_609_guard;
INSERT INTO _migration_609_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_609_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_609_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_609_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_609_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_609_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-physics-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/', 0, 1 FROM _migration_609_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
DELETE FROM _migration_609_guard;
INSERT INTO _migration_609_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_609_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 3 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_609_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 3 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_609_expected e ON e.id = q.id) = 3 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_609_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
DROP TABLE _migration_609_guard;
DROP TABLE _migration_609_expected;
DROP TABLE _migration_609_expected_parts;
